from PIL import Image
im=Image.open('/app/chess_board.png').convert('RGB')
files='abcdefgh'
for r in range(8):
 for c in range(8):
  # corner background average
  pts=[]
  for y in list(range(r*80+4,r*80+12))+list(range(r*80+68,r*80+76)):
   for x in list(range(c*80+4,c*80+12))+list(range(c*80+68,c*80+76)):
    pts.append(im.getpixel((x,y)))
  bg=tuple(sum(p[k] for p in pts)//len(pts) for k in range(3))
  vals=[]
  for y in range(r*80+5,r*80+75):
   for x in range(c*80+5,c*80+75):
    p=im.getpixel((x,y)); vals.append(sum((p[k]-bg[k])**2 for k in range(3))**0.5)
  if sum(v>25 for v in vals)>30:
   print(f'{files[c]}{8-r} bg={bg} changed={sum(v>25 for v in vals)}')
   for by in range(16):
    line=''
    for bx in range(16):
     pix=[]
     for y in range(r*80+8+by*4,r*80+12+by*4):
      for x in range(c*80+8+bx*4,c*80+12+bx*4):
       p=im.getpixel((x,y)); pix.append(sum(p)/3)
     lum=sum(pix)/len(pix)
     delta=lum-sum(bg)/3
     line += '@' if delta < -35 else '#' if delta > 35 else '+' if abs(delta)>15 else ' '
    print(line)
